{
  "language": {
    "operators": ["+", "-", "*", "/", "**"],
    "functions": ["sin", "cos", "tan", "exp", "log", "sqrt", "sinh", "cosh"],
    "constants": ["pi", "e"]
  },
  "simplifications": [
    {"id": "S01", "variables": ["x"], "expression": "(x**4 - 1)/(x**2 - 1)", "domain": "-3 < x < 3, x != -1, x != 1", "max_nodes": 6},
    {"id": "S02", "variables": ["x", "y"], "expression": "(sin(x)**2 + cos(x)**2)*(y**3-y)/(y*(y-1))", "domain": "-4 < x < 4; -3 < y < 3; y != 0, y != 1", "max_nodes": 4},
    {"id": "S03", "variables": ["x", "y"], "expression": "exp(log(x)) + log(exp(y))", "domain": "0.1 < x < 5; -3 < y < 3", "max_nodes": 4},
    {"id": "S04", "variables": ["a", "b"], "expression": "(a**3 + 3*a**2*b + 3*a*b**2 + b**3)/(a+b)", "domain": "-3 < a,b < 3; a+b != 0", "max_nodes": 6},
    {"id": "S05", "variables": ["x"], "expression": "sqrt(x**2 + 2*x + 1)", "domain": "-1 <= x < 6", "max_nodes": 4},
    {"id": "S06", "variables": ["x"], "expression": "1/cos(x)**2 - 1", "domain": "-1.3 < x < 1.3", "max_nodes": 5},
    {"id": "S07", "variables": ["x"], "expression": "sin(2*x)/(2*sin(x))", "domain": "-3 < x < 3; x != 0", "max_nodes": 3},
    {"id": "S08", "variables": ["x"], "expression": "log(x**3) - 3*log(x)", "domain": "0.1 < x < 6", "max_nodes": 2},
    {"id": "S09", "variables": ["x", "y"], "expression": "(x**2-y**2)/(x-y) + (x-y)**2/(x-y)", "domain": "-4 < x,y < 4; x != y", "max_nodes": 4},
    {"id": "S10", "variables": ["x"], "expression": "1/(1-x) + 1/(1+x)", "domain": "-2 < x < 2; x != -1, x != 1", "max_nodes": 9},
    {"id": "S11", "variables": ["x"], "expression": "(x**3+1)/(x+1)", "domain": "-4 < x < 4; x != -1", "max_nodes": 9},
    {"id": "S12", "variables": ["x", "y"], "expression": "sin(x+y)*cos(x-y) + cos(x+y)*sin(x-y)", "domain": "-3 < x,y < 3", "max_nodes": 5},
    {"id": "S13", "variables": ["a", "b", "c"], "expression": "(a/b)/(c/b)", "domain": "-4 < a,b,c < 4; b != 0, c != 0", "max_nodes": 4},
    {"id": "S14", "variables": ["x"], "expression": "sqrt(x)**2", "domain": "0 <= x < 9", "max_nodes": 2},
