  ],
  "identities": [
    {"id": "I01", "variables": ["x", "y"], "left": "(x+y)**3", "right": "x**3 + 3*x**2*y + 3*x*y**2 + y**3", "domain": "-4 < x,y < 4"},
    {"id": "I02", "variables": ["x", "y"], "left": "sin(x+y)", "right": "sin(x)*cos(y)+cos(x)*sin(y)", "domain": "-5 < x,y < 5"},
    {"id": "I03", "variables": ["x", "y"], "left": "log(x+y)", "right": "log(x)+log(y)", "domain": "0.2 < x,y < 5"},
    {"id": "I04", "variables": ["x"], "left": "sqrt(x**2)", "right": "x", "domain": "-5 < x < 5"},
    {"id": "I05", "variables": ["x"], "left": "(exp(x)-exp(-x))/2", "right": "sinh(x)", "domain": "-4 < x < 4"},
    {"id": "I06", "variables": ["x"], "left": "1+tan(x)**2", "right": "1/cos(x)**2", "domain": "-1.4 < x < 1.4"},
    {"id": "I07", "variables": ["x", "y"], "left": "(x**3-y**3)/(x-y)", "right": "x**2+x*y+y**2", "domain": "-5 < x,y < 5; x != y"},
    {"id": "I08", "variables": ["x", "y"], "left": "sqrt(x+y)", "right": "sqrt(x)+sqrt(y)", "domain": "0 <= x,y < 8"},
    {"id": "I09", "variables": ["x"], "left": "cos(2*x)", "right": "1-2*sin(x)**2", "domain": "-8 < x < 8"},
    {"id": "I10", "variables": ["a", "b", "c", "d"], "left": "(a+b)/(c+d)", "right": "a/c+b/d", "domain": "0.2 < a,b,c,d < 5"}
