#!/usr/bin/env python3
"""Equivalence-based, deterministic verifier for case 06."""

from __future__ import annotations

import ast
import json
import math
import random
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
INPUT = ROOT / "expressions.json"
OUTPUT = ROOT / "results.json"

FUNCS = {name: getattr(math, name) for name in ("sin", "cos", "tan", "exp", "log", "sqrt", "sinh", "cosh")}
CONSTS = {"pi": math.pi, "e": math.e}
ALLOWED_BINARY = (ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Pow)
ALLOWED_UNARY = (ast.UAdd, ast.USub)
EXPECTED_IDENTITIES = {
    "I01": True, "I02": True, "I03": False, "I04": False, "I05": True,
    "I06": True, "I07": True, "I08": False, "I09": True, "I10": False,
}


class VerificationError(Exception):
    pass


def fail(message: str) -> None:
    raise VerificationError(message)


def parse_expression(source: str, variables: list[str]) -> tuple[ast.Expression, int]:
    if not isinstance(source, str) or len(source) > 500:
        fail("候选表达式必须是长度不超过 500 的字符串")
    try:
        tree = ast.parse(source, mode="eval")
    except SyntaxError as exc:
        fail(f"表达式语法错误: {exc.msg}")
    for node in ast.walk(tree):
        if isinstance(node, (ast.Expression, ast.Load)):
            continue
        if isinstance(node, ast.BinOp):
            if not isinstance(node.op, ALLOWED_BINARY):
                fail("表达式包含不允许的二元运算")
        elif isinstance(node, ast.UnaryOp):
            if not isinstance(node.op, ALLOWED_UNARY):
                fail("表达式包含不允许的一元运算")
        elif isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name) or node.func.id not in FUNCS or len(node.args) != 1 or node.keywords:
                fail("表达式包含不允许的函数调用")
        elif isinstance(node, ast.Name):
            if node.id not in variables and node.id not in FUNCS and node.id not in CONSTS:
                fail(f"表达式包含未知名称 {node.id}")
        elif isinstance(node, ast.Constant):
            if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
                fail("表达式常量必须是实数")
        elif isinstance(node, (ast.operator, ast.unaryop)):
            pass
        else:
            fail(f"表达式包含不允许的语法 {type(node).__name__}")

    def complexity(node: ast.AST) -> int:
        if isinstance(node, ast.Expression):
            return complexity(node.body)
        if isinstance(node, (ast.Name, ast.Constant)):
            return 1
        if isinstance(node, ast.UnaryOp):
            return 1 + complexity(node.operand)
        if isinstance(node, ast.BinOp):
            return 1 + complexity(node.left) + complexity(node.right)
        if isinstance(node, ast.Call):
            return 1 + complexity(node.args[0])
        return 0

    return tree, complexity(tree)


def evaluate_node(node: ast.AST, env: dict[str, float]) -> float:
    if isinstance(node, ast.Expression):
        return evaluate_node(node.body, env)
    if isinstance(node, ast.Constant):
        return float(node.value)
    if isinstance(node, ast.Name):
        if node.id in env:
            return env[node.id]
        if node.id in CONSTS:
            return CONSTS[node.id]
        fail(f"无法求值名称 {node.id}")
    if isinstance(node, ast.UnaryOp):
        value = evaluate_node(node.operand, env)
        return value if isinstance(node.op, ast.UAdd) else -value
    if isinstance(node, ast.BinOp):
        left, right = evaluate_node(node.left, env), evaluate_node(node.right, env)
        if isinstance(node.op, ast.Add): return left + right
        if isinstance(node.op, ast.Sub): return left - right
        if isinstance(node.op, ast.Mult): return left * right
        if isinstance(node.op, ast.Div): return left / right
        if isinstance(node.op, ast.Pow):
            if abs(right) > 20:
                raise ValueError("幂指数过大")
            value = left ** right
            if isinstance(value, complex):
                raise ValueError("产生复数")
            return value
    if isinstance(node, ast.Call):
        return FUNCS[node.func.id](evaluate_node(node.args[0], env))
    raise ValueError("unsupported")


def evaluate(tree: ast.Expression, env: dict[str, float]) -> float:
    value = float(evaluate_node(tree, env))
    if not math.isfinite(value):
        raise ValueError("非有限结果")
    return value


def valid_domain(task_id: str, env: dict[str, float]) -> bool:
    g = env.get
    if task_id == "S01": return abs(g("x") - 1) > .08 and abs(g("x") + 1) > .08
    if task_id == "S02": return abs(g("y")) > .08 and abs(g("y") - 1) > .08
    if task_id == "S04": return abs(g("a") + g("b")) > .1
    if task_id == "S07": return abs(g("x")) > .08
    if task_id == "S09": return abs(g("x") - g("y")) > .1
    if task_id == "S10": return abs(g("x") - 1) > .08 and abs(g("x") + 1) > .08
    if task_id == "S11": return abs(g("x") + 1) > .08
    if task_id == "S13": return abs(g("b")) > .1 and abs(g("c")) > .1
    if task_id == "I07": return abs(g("x") - g("y")) > .1
    return True


RANGES = {
    "x": (-2.8, 2.8), "y": (-2.7, 2.7), "z": (-2.5, 2.5),
    "a": (-2.8, 2.8), "b": (-2.6, 2.6), "c": (-2.5, 2.5), "d": (-2.4, 2.4),
}


def probes(task: dict, count: int = 90) -> list[dict[str, float]]:
    task_id = task["id"]
    rng = random.Random(0x5A17 + sum(ord(c) for c in task_id))
    positive = task_id in {"S03", "S08", "S14", "S15", "I03", "I08", "I10"}
    out = []
    while len(out) < count:
        env = {}
        for name in task["variables"]:
            lo, hi = RANGES[name]
            if positive:
                lo, hi = (0.2, 5.0) if task_id != "S14" else (0.0, 8.8)
            env[name] = rng.uniform(lo, hi)
        if task_id == "S03":
            env["x"] = rng.uniform(0.1, 5.0)
            env["y"] = rng.uniform(-3.0, 3.0)
        if task_id == "S05": env["x"] = rng.uniform(-1.0, 5.8)
        if task_id == "S06": env["x"] = rng.uniform(-1.25, 1.25)
        if task_id == "S10": env["x"] = rng.uniform(-1.95, 1.95)
        if task_id == "I06": env["x"] = rng.uniform(-1.35, 1.35)
        if task_id == "I09": env["x"] = rng.uniform(-7.8, 7.8)
        if valid_domain(task_id, env):
            out.append(env)
    return out


def near(left: float, right: float) -> bool:
    return abs(left - right) <= 2e-9 + 2e-9 * max(abs(left), abs(right))


def indexed_results(items, expected_ids: set[str], label: str) -> dict[str, dict]:
    if not isinstance(items, list):
        fail(f"{label} 必须是数组")
    result = {}
    observed_order = []
    for index, item in enumerate(items):
        if not isinstance(item, dict) or not isinstance(item.get("id"), str):
            fail(f"{label}[{index}] 缺少字符串 id")
        if item["id"] in result:
            fail(f"{label} 中编号 {item['id']} 重复")
        result[item["id"]] = item
        observed_order.append(item["id"])
    if set(result) != expected_ids:
        fail(f"{label} 编号集合不匹配，缺少 {sorted(expected_ids-set(result))}，多出 {sorted(set(result)-expected_ids)}")
    if observed_order != sorted(observed_order):
        fail(f"{label} 必须按 id 升序排列")
    return result


def check_simplifications(tasks, submitted) -> None:
    by_id = indexed_results(submitted, {t["id"] for t in tasks}, "simplifications")
    for task in tasks:
        candidate = by_id[task["id"]].get("expression")
        original_tree, _ = parse_expression(task["expression"], task["variables"])
        candidate_tree, node_count = parse_expression(candidate, task["variables"])
        if node_count > task["max_nodes"]:
            fail(f"{task['id']} 有 {node_count} 个表达式节点，超过上限 {task['max_nodes']}")
        for env in probes(task):
            try:
                expected, actual = evaluate(original_tree, env), evaluate(candidate_tree, env)
            except (ArithmeticError, ValueError, OverflowError) as exc:
                fail(f"{task['id']} 在有效定义域内无法求值: {exc}")
            if not near(expected, actual):
                fail(f"{task['id']} 不等价；在 {env} 得到 {actual:.12g}，应为 {expected:.12g}")


def check_identities(tasks, submitted) -> None:
    by_id = indexed_results(submitted, {t["id"] for t in tasks}, "identities")
    for task in tasks:
        item = by_id[task["id"]]
        holds = item.get("holds")
        if not isinstance(holds, bool):
            fail(f"{task['id']}.holds 必须是布尔值")
        if holds != EXPECTED_IDENTITIES[task["id"]]:
            fail(f"{task['id']} 的恒等式判定错误")
        if not holds:
            env = item.get("counterexample")
            if not isinstance(env, dict) or set(env) != set(task["variables"]):
                fail(f"{task['id']} 必须给出包含全部变量且无额外键的 counterexample")
            clean = {}
            for name, value in env.items():
                if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(float(value)):
                    fail(f"{task['id']} 反例变量 {name} 必须是有限实数")
                clean[name] = float(value)
            identity_id = task["id"]
            in_domain = valid_domain(identity_id, clean)
            if identity_id == "I03":
                in_domain = in_domain and all(0.2 < v < 5 for v in clean.values())
            elif identity_id == "I04":
                in_domain = in_domain and -5 < clean["x"] < 5
            elif identity_id == "I08":
                in_domain = in_domain and all(0 <= v < 8 for v in clean.values())
            elif identity_id == "I10":
                in_domain = in_domain and all(0.2 < v < 5 for v in clean.values())
            if not in_domain:
                fail(f"{task['id']} 的反例不在给定定义域")
            left_tree, _ = parse_expression(task["left"], task["variables"])
            right_tree, _ = parse_expression(task["right"], task["variables"])
            try:
                difference = abs(evaluate(left_tree, clean) - evaluate(right_tree, clean))
            except (ArithmeticError, ValueError, OverflowError):
                fail(f"{task['id']} 的反例导致表达式无定义")
            if difference <= 1e-5:
                fail(f"{task['id']} 提交的反例差异不明显")


def main() -> int:
    if not OUTPUT.is_file():
        print("FAIL: 缺少 results.json", file=sys.stderr)
        return 1
    try:
        tasks = json.loads(INPUT.read_text(encoding="utf-8"))
        result = json.loads(OUTPUT.read_text(encoding="utf-8"))
        if not isinstance(result, dict):
            fail("results.json 顶层必须是对象")
        check_simplifications(tasks["simplifications"], result.get("simplifications"))
        check_identities(tasks["identities"], result.get("identities"))
    except (OSError, json.JSONDecodeError, VerificationError) as exc:
        print(f"FAIL: {exc}", file=sys.stderr)
        return 1
    print("PASS: 15 个化简结果数学等价，10 个恒等式判定及反例有效")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
